//! FFI wrappers for [`MetricsVec`] operations, called from C code.
//!
//! The corresponding C header is auto-generated by cheadergen at
//! `headers/metrics_ffi.h`.

use ffi::RLookupKey;
use index_result::{MetricsSlice, MetricsVec, RSIndexResult};

/// Creates an empty metrics collection. Does not allocate.
///
/// Use this to initialize the `metrics` field when constructing an
/// `RSIndexResult` in place on the C side. Zero-initialization (e.g.
/// designated initializers, `memset`, `calloc`) produces an invalid
/// `MetricsVec` because the underlying `ThinVec` represents the empty
/// state with a non-null sentinel pointer to a static header — not
/// `NULL`.
#[unsafe(no_mangle)]
pub const extern "C" fn MetricsVec_New() -> MetricsVec<'static> {
    MetricsVec::new()
}

/// Moves all metrics from `child` into `parent`, leaving `child` empty.
///
/// # Safety
///
/// 1. `parent` must point to a valid `MetricsVec` (e.g. `&result.metrics`).
/// 2. `child` must point to a valid `MetricsVec`, or be null (no-op).
#[unsafe(no_mangle)]
pub unsafe extern "C" fn RSYieldableMetric_Concat<'a>(
    parent: *mut MetricsVec<'a>,
    child: *mut MetricsVec<'a>,
) {
    debug_assert!(!parent.is_null(), "parent must not be null");
    if child.is_null() {
        return;
    }
    // SAFETY: caller guarantees both pointers are valid.
    let child = unsafe { &mut *child };
    if child.is_empty() {
        return;
    }
    // SAFETY: caller guarantees `parent` is a valid, non-null pointer.
    let parent = unsafe { &mut *parent };
    parent.concat(child);
}

/// Appends a single metric to the result's metrics collection.
///
/// # Safety
///
/// 1. `r` must point to a valid `RSIndexResult` and cannot be null.
/// 2. `key` must be a valid `*const RLookupKey` that outlives the result
///    (or null).
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ResultMetrics_Add(
    r: *mut RSIndexResult,
    key: *const RLookupKey,
    val: f64,
) {
    debug_assert!(!r.is_null(), "result must not be null");

    // SAFETY: caller guarantees validity (1).
    let result = unsafe { &mut *r };
    let metrics = result.metrics_mut();
    if key.is_null() {
        metrics.push_without_key(val);
    } else {
        // SAFETY: `key` is non-null (checked above) and valid per caller guarantee (2).
        metrics.push_with_key(unsafe { &*key }, val);
    }
}

/// Copies every metric in `source`'s subtree into `dst`, deepest first.
///
/// See [`RSIndexResult::flatten_metrics_into`] for the ordering guarantee and for when a
/// caller needs this rather than reading `source->metrics` directly.
///
/// # Safety
///
/// 1. `source` must point to a valid `RSIndexResult` and cannot be null.
/// 2. `dst` must point to a valid `MetricsVec` (e.g. `&result.metrics`).
/// 3. The `RLookupKey`s reachable from `source` must outlive `dst`, since `dst` keeps
///    borrowing them after this call returns.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn IndexResult_FlattenMetricsInto<'a>(
    source: *const RSIndexResult<'a>,
    dst: *mut MetricsVec<'a>,
) {
    debug_assert!(!source.is_null(), "source must not be null");
    debug_assert!(!dst.is_null(), "dst must not be null");

    // SAFETY: caller guarantees validity (1) and (3).
    let source = unsafe { &*source };
    // SAFETY: caller guarantees validity (2).
    let dst = unsafe { &mut *dst };
    source.flatten_metrics_into(dst);
}

/// Clears all entries from the result's metrics collection.
///
/// # Safety
///
/// 1. `r` must point to a valid `RSIndexResult` and cannot be null.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ResultMetrics_Reset(r: *mut RSIndexResult) {
    debug_assert!(!r.is_null(), "result must not be null");

    // SAFETY: caller guarantees validity (1).
    let result = unsafe { &mut *r };
    result.metrics.reset();
}

/// Resets aggregate-specific fields on an `RSIndexResult`: doc_id, freq,
/// field_mask, child records, and metrics.
///
/// # Safety
///
/// 1. `r` must point to a valid `RSIndexResult` and cannot be null.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn IndexResult_ResetAggregate(r: *mut RSIndexResult) {
    debug_assert!(!r.is_null(), "result must not be null");

    // SAFETY: caller guarantees validity (1).
    let result = unsafe { &mut *r };
    result.reset_aggregate();
}

/// Returns a read-only slice view of the metrics collection for zero-copy
/// iteration from C.
///
/// # Safety
///
/// 1. `metrics` must point to a valid `MetricsVec` (e.g. `&result.metrics`).
/// 2. The returned slice borrows from the `MetricsVec`; the caller must
///    not mutate or free the `MetricsVec` while the slice is in use.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn MetricsVec_AsSlice(metrics: *const MetricsVec) -> MetricsSlice {
    debug_assert!(!metrics.is_null(), "metrics must not be null");

    // SAFETY: caller guarantees validity (1).
    let vec = unsafe { &*metrics };
    vec.as_metrics_slice()
}

/// Sets the value carried under `key`, appending a new entry if none carries it yet.
///
/// See [`MetricsVec::upsert_with_key`] for which metrics belong here rather than in
/// [`ResultMetrics_Add`].
///
/// # Safety
///
/// 1. `metrics` must point to a valid `MetricsVec` (e.g. `&result.metrics`).
/// 2. `key` must point to a valid `RLookupKey` that outlives the collection, since an
///    absent key is stored rather than ignored. Compared by pointer identity.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn MetricsVec_UpsertValue<'a>(
    metrics: *mut MetricsVec<'a>,
    key: *const RLookupKey,
    new_value: f64,
) {
    debug_assert!(!metrics.is_null(), "metrics must not be null");
    debug_assert!(!key.is_null(), "key must not be null");

    // SAFETY: caller guarantees validity (1).
    let vec = unsafe { &mut *metrics };
    // SAFETY: caller guarantees `key` is valid, non-null and outlives the collection (2);
    // non-null is checked by the debug_assert above.
    let key = unsafe { &*key };
    vec.upsert_with_key(key, new_value);
}
